codons = []
sample = "AUGGCCAUGGCGCCCAGAACUGAGAUCAAUAGUACCCGUAUUAACGGGUGA"
protein = ""
def segmentation(rna_string): 
    # prepare the string
    for i in range(0, len(rna_string),3):
        codons.append(rna_string[i : i + 3])
    return codons

def translateProtein(rna_string):

    codons = segmentation(rna_string)
    protein = ""

    for codon in codons:
        if codon in ("UUU", "UUC"):
            protein += "F"
        elif codon in ("UUA", "UUG", "CUU", "CUC", "CUA", "CUG"):
            protein += "L"
        elif codon in ("AUU", "AUC", "AUA"):
            protein += "I"
        elif codon == "AUG":
            protein += "M"
        elif codon in ("GUU", "GUC", "GUA", "GUG"):
            protein += "V"
        elif codon in ("UCU", "UCC", "UCA", "UCG", "AGU", "AGC"):
            protein += "S"
        elif codon in ("CCU", "CCC", "CCA", "CCG"):
            protein += "P"
        elif codon in ("ACU", "ACC", "ACA", "ACG"):
            protein += "T"
        elif codon in ("GCU", "GCC", "GCA", "GCG"):
            protein += "A"
        elif codon in ("UAU", "UAC"):
            protein += "Y"
        elif codon in ("CAU", "CAC"):
            protein += "H"
        elif codon in ("CAA", "CAG"):
            protein += "Q"
        elif codon in ("AAU", "AAC"):
            protein += "N"
        elif codon in ("AAA", "AAG"):
            protein += "K"
        elif codon in ("GAU", "GAC"):
            protein += "D"
        elif codon in ("GAA", "GAG"):
            protein += "E"
        elif codon in ("UGU", "UGC"):
            protein += "C"
        elif codon == "UGG":
            protein += "W"
        elif codon in ("CGU", "CGC", "CGA", "CGG", "AGA", "AGG"):
            protein += "R"
        elif codon in ("GGU", "GGC", "GGA", "GGG"):
            protein += "G"
        elif codon in ("UAA", "UAG", "UGA"):
            break  # Stop codon

    return protein


print(translateProtein(""))
